'use strict';
const E=QuizEngine, cards=QUIZ_CARDS, byId=new Map(cards.map(c=>[c.id,c])), key='declic-marketing-v1';
const $=id=>document.getElementById(id);let filter='all',s,resetAll=true,storageWorks=true;
function fresh(){return E.initial(E.shuffle(cards.map(c=>c.id)));}
try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&saved.version===1&&Array.isArray(saved.queue)&&Array.isArray(saved.mastered)){const ids=[...saved.queue,...saved.mastered];if(ids.length===cards.length&&new Set(ids).size===cards.length&&ids.every(id=>byId.has(id))&&Number.isFinite(saved.attempts)&&Number.isFinite(saved.wrong)){s=saved;filter=typeof s.filter==='string'?s.filter:'all';}}}catch{storageWorks=false;}
if(!s)s=fresh();
// Display only the selected chapter, without discarding progress on other chapters.
function matches(id){return filter==='all'||byId.get(id).chapter===filter;}
function activeQueue(){return s.queue.filter(matches);}
function selectedCards(){return cards.filter(c=>filter==='all'||c.chapter===filter);}
function save(){s.filter=filter;try{localStorage.setItem(key,JSON.stringify(s));}catch{storageWorks=false;}$('save-status').textContent=storageWorks?'Progression sauvegardée':'Progression conservée pour cette session';}
function current(){return byId.get(activeQueue()[0]);}
function render(focus=false){const ids=activeQueue(),selected=selectedCards(),m=s.mastered.filter(matches).length,pct=Math.round(m/selected.length*100)||0;
$('percent').textContent=pct+' %';$('progressbar').setAttribute('aria-valuenow',pct);$('fill').style.width=pct+'%';$('mastered').textContent=m;$('total').textContent=selected.length;$('remaining').textContent=ids.length;$('wrong').textContent=s.history.filter(x=>!x.good&&matches(x.id)).length;$('scope').textContent=selected.length+' questions pour couvrir '+(filter==='all'?'les 16 chapitres de ton document.':'ce chapitre.');$('attempts').textContent=s.history.filter(x=>matches(x.id)).length+' réponses évaluées · '+m+' bonnes réponses';$('quiz').classList.toggle('hidden',!ids.length);$('finished').classList.toggle('hidden',!!ids.length);
if(!ids.length){$('finish-text').textContent=`Tu as réussi les ${selected.length} questions de ${filter==='all'?'tout le cours':'ce chapitre'}. Elles sont toutes mises de côté.`;save();return;}
const c=current();$('topic').textContent=c.chapter;$('session-count').textContent=ids.length+' à travailler';$('question').textContent=c.question;$('answer').value=s.draft||'';$('answer').readOnly=!!s.revealed;$('correction').textContent=c.answer.replace(/^\* /gm,'• ');$('reveal-actions').classList.toggle('hidden',!!s.revealed);$('correction-zone').classList.toggle('hidden',!s.revealed);$('reveal').disabled=!$('answer').value.trim();save();if(focus)$('answer').focus();}
function reveal(skip=false){if(s.revealed||!current())return;if(!skip&&!$('answer').value.trim())return;s.draft=$('answer').value;s.revealed=true;render();$('correction-zone').scrollIntoView({behavior:'smooth',block:'nearest'});}
function grade(good){if(!s.revealed)return;const c=current();if(!c)return;
// Grade the selected card using the same queue rule, then merge untouched chapters back.
const visible=activeQueue();const scoped={...s,queue:visible,mastered:[...s.mastered],history:[...s.history]};const next=E.grade(scoped,good);const other=s.queue.filter(id=>!matches(id));s={...next,queue:[...next.queue,...other]};render(true);$('toast').textContent=good?'Bien joué. Cette question est mise de côté.':next.queue.length>1?'On la reverra après '+Math.min(3,next.queue.length-1)+' autre(s) question(s).':'Il ne reste que cette question à revoir. Prends un instant, puis réessaie.';}
const chapterNames=[...new Set(cards.map(c=>c.chapter))];for(const c of chapterNames){const o=document.createElement('option');o.value=c;o.textContent=c;$('chapter').appendChild(o);}if(!chapterNames.includes(filter)&&filter!=='all')filter='all';$('chapter').value=filter;
$('chapter').addEventListener('change',()=>{filter=$('chapter').value;s.draft='';s.revealed=false;$('toast').textContent='';render();});$('answer').addEventListener('input',()=>{s.draft=$('answer').value;$('reveal').disabled=!s.draft.trim();save();});$('answer').addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();reveal();}});$('reveal').onclick=()=>reveal();$('dont-know').onclick=()=>reveal(true);$('good').onclick=()=>grade(true);$('bad').onclick=()=>grade(false);
function askReset(all){resetAll=all;$('reset-dialog').querySelector('p').textContent=all?'Toutes les questions et tous les compteurs seront réinitialisés. Cette action ne peut pas être annulée.':'Les questions et compteurs du chapitre seront réinitialisés. Les autres chapitres seront conservés.';$('reset-dialog').showModal();}
$('reset').onclick=()=>askReset(true);$('restart-filter').onclick=()=>askReset(filter==='all');$('cancel-reset').onclick=()=>$('reset-dialog').close();$('confirm-reset').onclick=()=>{if(resetAll){s=fresh();filter='all';$('chapter').value=filter;}else{const ids=selectedCards().map(c=>c.id);s.queue=[...E.shuffle(ids),...s.queue.filter(id=>!matches(id))];s.mastered=s.mastered.filter(id=>!matches(id));s.history=s.history.filter(x=>!matches(x.id));s.attempts=s.history.length;s.wrong=s.history.filter(x=>!x.good).length;s.draft='';s.revealed=false;}$('reset-dialog').close();$('toast').textContent='Nouvelle session, on y va !';render(true);};render();
